const RAMPA_LOCATIONS={chintapalle:{title:"Chintapalle Police Station Raid",desc:"On August 22, 1922, Alluri Sitarama Raju and 300 tribal insurgents launched their first major attack on Chintapalle police station, capturing 11 guns and 1,390 rounds of ammunition."},krishnadevipeta:{title:"KD Peta (Krishnadevipeta) Raid",desc:"On August 23, 1922, Raju raided KD Peta police station, seizing weapons and leaving a signed entry in the police station register announcing his defiance."},addateegala:{title:"Addateegala Encounter",desc:"On August 24, 1922, the rebels raided Addateegala station. Sub-inspector and constables surrendered without resistance as Adivasis asserted control over Agency tracts."},rampa:{title:"Rampachodavaram & Peddavalasa",desc:"In September 1922, British officers Scott and Heaney were ambushed and killed at Peddavalasa, proving the effectiveness of Raju's hill warfare tactics."}},RAMPA_TIMELINE=[{date:"August 1922",event:"First series of police station raids at Chintapalle, KD Peta, and Addateegala."},{date:"September 1922",event:"Ambush at Peddavalasa; British officers Scott and Heaney killed."},{date:"June 1923",event:"British deploy Malabar Special Police and Assam Rifles to Agency areas."},{date:"April 1924",event:"British authorities initiate massive blockade of tribal villages to cut off supplies."},{date:"May 7, 1924",event:"Alluri Sitarama Raju captured at Mampa/Koyyuru jungle and martyred."}];document.addEventListener("DOMContentLoaded",()=>{const e=document.getElementById("rampa-loc-title"),a=document.getElementById("rampa-loc-desc"),t=document.getElementById("rampa-timeline");window.selectRampaLoc=function(t){const i=RAMPA_LOCATIONS[t];i&&e&&(e.textContent=i.title,a.textContent=i.desc)},t&&(t.innerHTML=RAMPA_TIMELINE.map(e=>`\n            <div class="rampa-tl-item">\n                <div class="rampa-tl-year">${e.date}</div>\n                <div style="font-size:1.05rem;">${e.event}</div>\n            </div>\n        `).join(""))});